from config import parse_config


def test_basic():
    assert parse_config("host=localhost\nport=8080") == {"host": "localhost", "port": "8080"}


def test_comments_with_equals_skipped():
    text = "# db_url=postgres://h/db\nhost=localhost\n# timeout=30\nport=5432"
    assert parse_config(text) == {"host": "localhost", "port": "5432"}


def test_hash_inside_value_preserved():
    text = "color=#ff0000\ntag=v1.0#beta\nfrag=page#section"
    cfg = parse_config(text)
    assert cfg["color"] == "#ff0000"
    assert cfg["tag"] == "v1.0#beta"
    assert cfg["frag"] == "page#section"


def test_indented_comment_skipped():
    assert parse_config("   # note=x\nname=test") == {"name": "test"}


def test_blank_lines():
    assert parse_config("\n\nkey=val\n\n") == {"key": "val"}

