def parse_config(text):
    """Parse a key=value config into a dict.

    One pair per line, split on the first '='. Comment lines are ignored.
    Blank lines are ignored.
    """
    result = {}
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        if line.startswith('#'):
            continue
        if '=' in line:
            key, _, value = line.partition('=')
            result[key.strip()] = value.strip()
    return result
